import { Component, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../../../services/data.service';

@Component({
  selector: 'app-dashboard-reportes',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './reportes.component.html',
  styleUrl: './reportes.component.css'
})
export class ReportesComponent {
  constructor(public data: DataService) {}

  // ---- Ventas ----
  totalVentas = computed(() => this.data.ventas().reduce((sum, v) => sum + v.total, 0));
  promedioVenta = computed(() => {
    const n = this.data.ventas().length;
    return n === 0 ? 0 : this.totalVentas() / n;
  });

  // ---- Citas por estado ----
  citasPorEstado = computed(() => {
    const estados: Array<'Pendiente' | 'Confirmada' | 'Finalizada' | 'Cancelada'> =
      ['Pendiente', 'Confirmada', 'Finalizada', 'Cancelada'];
    const citas = this.data.citas();
    const conteo = estados.map(estado => ({
      estado,
      cantidad: citas.filter(c => c.estado === estado).length
    }));
    const max = Math.max(1, ...conteo.map(c => c.cantidad));
    return conteo.map(c => ({ ...c, porcentaje: Math.round((c.cantidad / max) * 100) }));
  });

  // ---- Servicios más agendados ----
  serviciosPopulares = computed(() => {
    const citas = this.data.citas();
    const conteoMap = new Map<string, number>();
    citas.forEach(c => conteoMap.set(c.servicio, (conteoMap.get(c.servicio) ?? 0) + 1));
    const lista = Array.from(conteoMap.entries()).map(([servicio, cantidad]) => ({ servicio, cantidad }));
    lista.sort((a, b) => b.cantidad - a.cantidad);
    const max = Math.max(1, ...lista.map(l => l.cantidad));
    return lista.map(l => ({ ...l, porcentaje: Math.round((l.cantidad / max) * 100) }));
  });

  // ---- Inventario ----
  productosBajoStock = computed(() => this.data.productos().filter(p => p.existencias <= p.minimo));
  clientesTotal = computed(() => this.data.clientes().length);

  formatPrecio(valor: number): string {
    return '$' + Math.round(valor).toLocaleString('es-CO');
  }

  exportarVentasCsv() {
    const filas = [['Cliente', 'Detalle', 'Fecha', 'Total']];
    this.data.ventas().forEach(v => filas.push([v.cliente, v.detalle, v.fecha, String(v.total)]));
    const contenido = filas.map(f => f.map(campo => `"${campo.replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([contenido], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const enlace = document.createElement('a');
    enlace.href = url;
    enlace.download = 'ventas-emilker.csv';
    enlace.click();
    URL.revokeObjectURL(url);
  }
}
<header class="content-header">
  <div>
    <p class="eyebrow">Reportes</p>
    <h1>Estadísticas del negocio</h1>
  </div>
  <button class="btn-outline" style="width:auto; padding:10px 18px;" (click)="exportarVentasCsv()">
    Exportar ventas (CSV)
  </button>
</header>

<section class="metrics">
  <div class="metric">
    <p class="metric-label">Total en ventas</p>
    <p class="metric-value">{{ formatPrecio(totalVentas()) }}</p>
  </div>
  <div class="metric">
    <p class="metric-label">Venta promedio</p>
    <p class="metric-value">{{ formatPrecio(promedioVenta()) }}</p>
  </div>
  <div class="metric">
    <p class="metric-label">Clientes</p>
    <p class="metric-value">{{ clientesTotal() }}</p>
  </div>
  <div class="metric metric-warn">
    <p class="metric-label">Bajo stock</p>
    <p class="metric-value">{{ productosBajoStock().length }}</p>
  </div>
</section>

<section class="panels">
  <div class="panel">
    <div class="panel-head"><h2>Citas por estado</h2></div>
    <div class="bar-row" *ngFor="let c of citasPorEstado()">
      <span class="bar-label">{{ c.estado }}</span>
      <div class="bar-track">
        <div class="bar-fill" [style.width.%]="c.porcentaje"></div>
      </div>
      <span class="bar-value">{{ c.cantidad }}</span>
    </div>
  </div>

  <div class="panel">
    <div class="panel-head"><h2>Servicios más agendados</h2></div>
    <div class="bar-row" *ngFor="let s of serviciosPopulares()">
      <span class="bar-label">{{ s.servicio }}</span>
      <div class="bar-track">
        <div class="bar-fill gold" [style.width.%]="s.porcentaje"></div>
      </div>
      <span class="bar-value">{{ s.cantidad }}</span>
    </div>
    <p class="empty-hint" *ngIf="serviciosPopulares().length === 0">Aún no hay citas registradas.</p>
  </div>
</section>

<section class="panel" style="margin-top:20px;">
  <div class="panel-head"><h2>Inventario en alerta</h2></div>
  <table class="data-table">
    <thead><tr><th>Producto</th><th>Existencias</th><th>Mínimo</th></tr></thead>
    <tbody>
      <tr *ngFor="let p of productosBajoStock()">
        <td>{{ p.nombre }}</td>
        <td>{{ p.existencias }}</td>
        <td>{{ p.minimo }}</td>
      </tr>
    </tbody>
  </table>
  <p class="empty-hint" *ngIf="productosBajoStock().length === 0">Todo el inventario está en buen nivel.</p>
</section>
